1	import React, { createContext, useContext, useEffect, useState } from 'react';
2	import { supabase } from '../lib/supabase';
3	import { getMeuPlanoStatus } from '../services/restauranteService';
4	
5	const AuthContext = createContext({})
6	
7	export const useAuth = () => {
8	  const context = useContext(AuthContext)
9	  if (!context) {
10	    throw new Error('useAuth must be used within AuthProvider')
11	  }
12	  return context
13	}
14	
15	export const AuthProvider = ({ children }) => {
16	  const [user, setUser] = useState(null)
17	  const [userProfile, setUserProfile] = useState(null)
18	  const [loading, setLoading] = useState(true)
19	  const [authError, setAuthError] = useState(null)
20	  const [planoStatus, setPlanoStatus] = useState(null)
21	
22	  useEffect(() => {
23	    // Get initial session - Use Promise chain
24	    supabase?.auth?.getSession()?.then(({ data: { session } }) => {
25	        if (session?.user) {
26	          setUser(session?.user)
27	          fetchUserProfile(session?.user?.id)
28	        }
29	        setLoading(false)
30	      })?.catch((error) => {
31	        setAuthError('Failed to get session. Please check your Supabase connection.')
32	        setLoading(false)
33	      })
34	
35	    // Listen for auth changes - NEVER ASYNC callback
36	    const { data: { subscription } } = supabase?.auth?.onAuthStateChange(
37	      (event, session) => {
38	        if (session?.user) {
39	          setUser(session?.user)
40	          fetchUserProfile(session?.user?.id)
41	        } else {
42	          setUser(null)
43	          setUserProfile(null)
44	        }
45	        setLoading(false)
46	        setAuthError(null)
47	      }
48	    )
49	
50	    return () => subscription?.unsubscribe()
51	  }, [])
52	
53	  // Status da assinatura do plano — só relevante pro dono, carregado 1x por
54	  // sessão (RestauranteGuard usa isso pra bloquear o painel se estiver vencido).
55	  const refreshPlanoStatus = () => {
56	    if (userProfile?.role !== 'restaurant_owner') return;
57	    getMeuPlanoStatus().then(setPlanoStatus).catch(() => {});
58	  };
59	
60	  useEffect(() => {
61	    if (userProfile?.role === 'restaurant_owner') {
62	      getMeuPlanoStatus().then(setPlanoStatus).catch((error) => {
63	        if (error?.message === 'Essas credenciais não pertencem a esta loja') {
64	          setAuthError('Este acesso não pertence a esta loja. Faça login pelo domínio correto do seu restaurante.');
65	          signOut();
66	        }
67	      });
68	    } else {
69	      setPlanoStatus(null);
70	    }
71	  }, [userProfile?.role])
72	
73	  const fetchUserProfile = (userId) => {
74	    return supabase?.from('user_profiles')?.select('*')?.eq('id', userId)?.single()?.then(({ data, error }) => {
75	        if (error) {
76	          setAuthError(`Failed to fetch user profile: ${error?.message}`)
77	          return
78	        }
79	        setUserProfile(data)
80	      })
81	  }
82	
83	  const signIn = async (email, password) => {
84	    setAuthError(null)
85	    setLoading(true)
86	    
87	    try {
88	      const { data, error } = await supabase?.auth?.signInWithPassword({
89	        email,
90	        password
91	      })
92	      
93	      if (error) {
94	        setAuthError(error?.message)
95	        return { success: false, error: error?.message };
96	      }
97	      
98	      return { success: true, user: data?.user };
99	    } catch (error) {
100	      if (error?.message?.includes('Failed to fetch') || 
101	          error?.message?.includes('AuthRetryableFetchError')) {
102	        setAuthError('Cannot connect to authentication service. Your Supabase project may be paused or inactive. Please check your Supabase dashboard and resume your project if needed.')
103	        return { success: false, error: 'Connection failed' }
104	      }
105	      
106	      setAuthError('Something went wrong. Please try again.')
107	      return { success: false, error: 'Authentication failed' }
108	    } finally {
109	      setLoading(false)
110	    }
111	  }
112	
113	  const signUp = async (email, password, userData = {}) => {
114	    setAuthError(null)
115	    setLoading(true)
116	    
117	    try {
118	      const { data, error } = await supabase?.auth?.signUp({
119	        email,
120	        password,
121	        options: {
122	          data: {
123	            name: userData?.name || email?.split('@')?.[0],
124	            role: userData?.role || 'customer',
125	            ...userData
126	          }
127	        }
128	      })
129	      
130	      if (error) {
131	        setAuthError(error?.message)
132	        return { success: false, error: error?.message };
133	      }
134	      
135	      return { success: true, user: data?.user };
136	    } catch (error) {
137	      if (error?.message?.includes('Failed to fetch') || 
138	          error?.message?.includes('AuthRetryableFetchError')) {
139	        setAuthError('Cannot connect to authentication service. Your Supabase project may be paused or inactive. Please check your Supabase dashboard and resume your project if needed.')
140	        return { success: false, error: 'Connection failed' }
